      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "Em aplicações offshore com turbinas a gás, confiabilidade, disponibilidade e mantenabilidade são apresentadas como aspectos relevantes para operação e economia da planta, e o desempenho do equipamento depende também do projeto, operação e manutenção adequados de subsistemas auxiliares, instrumentação e controle.",
          "trechos": [
